from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, ForceSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
Touch_Sensor = ForceSensor(Port.F)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 150)
MM_Left = Motor(Port.C, Direction.CLOCKWISE)
MM_Right = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 200
turnAmount = 10
mission = 0
max_mission = 3
running = 0
targetAngle = 0
currentAngle = 0
error = 0
correction = 0
Kp = 2
distance = 0

def DriveStraight(dist, speed):
    global targetAngle, baseSpeed, currentAngle, error, correction
    drive_base.use_gyro(True)
    drive_base.reset(0, 0)
    targetAngle = 0
    drive_base.settings(straight_acceleration=400)
    baseSpeed = speed
    while not drive_base.distance() >= dist:
        currentAngle = drive_base.angle()
        error = targetAngle - currentAngle
        correction = Kp * error
        drive_base.drive(baseSpeed, correction)
    drive_base.straight(0)


# The main program starts here.
DriveStraight(780, 500)
drive_base.turn(-100)
print(drive_base.angle())
wait(0)
DriveStraight(150, 330)
wait(2000)
drive_base.settings(straight_speed=500)
drive_base.straight(-130)
wait(2000)
drive_base.turn(-30)
wait(2000)
drive_base.straight(-90)
wait(2000)
drive_base.turn(100)
# then turn and come back!
wait(2000)
drive_base.turn(30)
wait(0)
DriveStraight(80, 400)
wait(0)
drive_base.turn(90)
wait(0)
DriveStraight(750, 700)
